# -*- coding: utf-8 -*-
# patch_iskra_chat.py
# ============================================================
# ПАТЧ: рабочий чат с Искрой + убран дубль в чат.
# Спринт 45 · 2026-06-16
#
#   1. iskra_live.py — новая функция chat_with_iskra():
#      Искра отвечает в РАБОЧЕМ режиме, зная свой последний прогон
#      (narrative+signal+market). Без обращения к терминалу — болтовня
#      не поднимает MT5. Нет прогона -> честно просит нажать РЫНОК.
#   2. ui_exchange.py:
#      - РЫНОК сохраняет рабочий контекст прогона (iskra_last_run)
#      - чат (send_message) подаёт Искре этот контекст -> она помнит отчёт
#      - убрана обрезка-дубль [:160]; в чат идёт приглашение к разговору,
#        полный голос остаётся в отчёте.
#
# Бэкап (.bak). Запуск из корня репо:  python patch_iskra_chat.py
# ============================================================
import base64, os, shutil
FILES = {
    "studio/modules/trading/iskra_live.py": "",
    "studio/economy/ui_exchange.py": ""
}
def main():
    root = os.getcwd()
    print("=== ПАТЧ: рабочий чат с Искрой ===")
    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            shutil.copy2(path, path + ".bak")
            print(f"  [BAK] {dest}.bak")
        open(path, "wb").write(base64.b64decode(b64))
        print(f"  [OK ] {dest}")
    print("=== ГОТОВО ===")
    print("Теперь: нажми РЫНОК (Искра отработает), потом")
    print("кликни её пузырёк A01 и спроси в чате 'почему молчишь?' —")
    print("она ответит конкретно про свой прогон, зная свой отчёт.")
if __name__ == "__main__":
    main()
